# rough estimate (real tokenizers vary by model)
def est_tokens(text: str) -> int:
    return max(1, len(text) // 4)

est_tokens("The agent loops until done.")  # ~7 tokens

def fit(history, max_tokens):
    while est_tokens(render(history)) > max_tokens and len(history) > 1:
        history.pop(0)   # evict oldest turn (lossy!)
    return history
